// Des: Tests for sy-clou-sqlz and the Turso, Neon, TiDB request builders
// Flo: escape hostile text > upserts per dialect > request shapes > reply checks
// I/O: strings, fake transport > pass or fail
// Run: zig build test
// ===================================================================
const std = @import("std"); const sqlz = @import("sy-clou-sqlz.zig"); const base = @import("nt-vend-base.zig"); const turs = @import("sy-clou-turs.zig"); const neon = @import("sy-clou-neon.zig"); const tidb = @import("sy-clou-tidb.zig"); const cfgz = @import("cf-conf-load.zig");
const allo = std.testing.allocator;
fn arenNew() std.heap.ArenaAllocator { return std.heap.ArenaAllocator.init(allo); }
test "literals double quotes, MySQL also doubles backslashes, NUL refused" { var aren = arenNew(); defer aren.deinit(); const a = aren.allocator(); try std.testing.expectEqualStrings("'it''s'", try sqlz.lit(a, .sqlt, "it's")); try std.testing.expectEqualStrings("'a\\b'", try sqlz.lit(a, .pgsq, "a\\b")); try std.testing.expectEqualStrings("'a\\\\b'", try sqlz.lit(a, .mysq, "a\\b")); try std.testing.expectEqualStrings("'x''; DROP TABLE t;--'", try sqlz.lit(a, .sqlt, "x'; DROP TABLE t;--")); try std.testing.expectError(error.BadText, sqlz.lit(a, .sqlt, "a\x00b")); }
test "upsert per dialect" { var aren = arenNew(); defer aren.deinit(); const a = aren.allocator(); const cols = [_]sqlz.Col{ .{ .name = "k", .valu = "'1'" }, .{ .name = "v", .valu = "'x'" } }; try std.testing.expectEqualStrings("INSERT INTO t(k,v) VALUES('1','x') ON CONFLICT(k) DO UPDATE SET v=excluded.v", try sqlz.upsert(a, .sqlt, "t", "k", &cols)); try std.testing.expectEqualStrings("INSERT INTO t(k,v) VALUES('1','x') ON CONFLICT(k) DO UPDATE SET v=excluded.v", try sqlz.upsert(a, .pgsq, "t", "k", &cols)); try std.testing.expectEqualStrings("INSERT INTO t(k,v) VALUES('1','x') ON DUPLICATE KEY UPDATE v=VALUES(v)", try sqlz.upsert(a, .mysq, "t", "k", &cols)); }
test "Turso: one pipeline POST, Bearer, close at the end; error results detected" { var aren = arenNew(); defer aren.deinit(); const a = aren.allocator(); const http = try turs.reqBuild(a, .{ .hostz = "db-org.turso.io" }, "TOK", &.{ "SELECT 1", "SELECT 2" }); try std.testing.expectEqualStrings("https://db-org.turso.io/v2/pipeline", http.urlz); try std.testing.expectEqualStrings("Bearer TOK", http.auth); try std.testing.expectEqualStrings("{\"requests\":[{\"type\":\"execute\",\"stmt\":{\"sql\":\"SELECT 1\"}},{\"type\":\"execute\",\"stmt\":{\"sql\":\"SELECT 2\"}},{\"type\":\"close\"}]}", http.body); const okb = try allo.dupe(u8, "{\"results\":[{\"type\":\"ok\"},{\"type\":\"ok\"},{\"type\":\"ok\"}]}"); defer allo.free(okb); try turs.rspChek(a, .{ .code = 200, .body = okb }); const bad = try allo.dupe(u8, "{\"results\":[{\"type\":\"ok\"},{\"type\":\"error\",\"error\":{\"message\":\"x\"}}]}"); defer allo.free(bad); try std.testing.expectError(error.CloudSql, turs.rspChek(a, .{ .code = 200, .body = bad })); const junk = try allo.dupe(u8, "nope"); defer allo.free(junk); try std.testing.expectError(error.CloudSql, turs.rspChek(a, .{ .code = 200, .body = junk })); try std.testing.expectError(error.BadConfig, turs.reqBuild(a, .{}, "T", &.{})); }
test "Neon: connection string header, JSON query" { var aren = arenNew(); defer aren.deinit(); const http = try neon.reqBuild(aren.allocator(), .{ .hostz = "ep-x.neon.tech" }, "postgres://u:p@h/db", "SELECT 1"); try std.testing.expectEqualStrings("https://ep-x.neon.tech/sql", http.urlz); try std.testing.expectEqualStrings("Neon-Connection-String", http.extra[0].name); try std.testing.expectEqualStrings("{\"query\":\"SELECT 1\"}", http.body); try std.testing.expectError(error.CloudSql, neon.rspChek(.{ .code = 400, .body = @constCast("") })); }
test "TiDB: Basic auth, database header, host and db required" { var aren = arenNew(); defer aren.deinit(); const a = aren.allocator(); const http = try tidb.reqBuild(a, .{ .hostz = "http-gw.tidbcloud.com", .dbnm = "scra" }, "user:pass", "SELECT 1"); try std.testing.expectEqualStrings("https://http-gw.tidbcloud.com/v1beta/sql", http.urlz); try std.testing.expectEqualStrings("Basic dXNlcjpwYXNz", http.auth); try std.testing.expectEqualStrings("scra", http.extra[0].valu); try std.testing.expectError(error.BadConfig, tidb.reqBuild(a, .{ .hostz = "h" }, "u:p", "S")); }
test "Net client routes by kind and surfaces cloud errors" { const Fake = struct { code: u16, seen: usize = 0, pub fn send(self: *@This()) base.Send { return .{ .ctx = self, .call = callz }; } fn callz(ctx: *anyopaque, gpaz: std.mem.Allocator, _: std.Io, _: base.Http) anyerror!base.Back { const self: *@This() = @ptrCast(@alignCast(ctx)); self.seen += 1; return .{ .code = self.code, .body = try gpaz.dupe(u8, "{\"results\":[{\"type\":\"ok\"}]}") }; } }; var aren = arenNew(); defer aren.deinit(); var fak: Fake = .{ .code = 200 }; var net: sqlz.Net = .{ .kind = .neon, .ep = .{ .hostz = "h" }, .key = "k", .send = fak.send(), .gpaz = allo }; const sq = net.sql(); try std.testing.expectEqual(sqlz.Dial.pgsq, sq.dial); try sq.exec(sq.ctx, aren.allocator(), std.testing.io, &.{ "A", "B", "C" }); try std.testing.expectEqual(@as(usize, 3), fak.seen); fak.code = 500; try std.testing.expectError(error.CloudSql, sq.exec(sq.ctx, aren.allocator(), std.testing.io, &.{"A"})); }
